<?php
declare(strict_types=1); require_once __DIR__.'/admin-layout.php'; require_once __DIR__.'/../models/Destination.php';
$m=new Destination();$flash=getFlashMessage();$message=$flash['message']??'';$type=$flash['type']??'success';$editing=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!verifyAdminCsrf())throw new RuntimeException('Security token expired. Refresh the page.');$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='save'){ $name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Destination name is required.');$status=$_POST['status']??'ACTIVE';if(!in_array($status,['ACTIVE','INACTIVE'],true))throw new RuntimeException('Invalid status.');foreach(['latitude','longitude'] as $k){if(($_POST[$k]??'')!==''&&!is_numeric($_POST[$k]))throw new RuntimeException(ucfirst($k).' must be numeric.');}$d=['name'=>$name,'state'=>trim($_POST['state']??''),'country'=>trim($_POST['country']??'India'),'latitude'=>trim($_POST['latitude']??''),'longitude'=>trim($_POST['longitude']??''),'description'=>trim($_POST['description']??''),'image'=>trim($_POST['image']??''),'status'=>$status];if($id)$m->update($id,$d);else$m->create($d);$success=$id?'Destination updated successfully.':'Destination added successfully.';setFlashMessage($success);header('Location: destinations.php');exit;}elseif($a==='delete'){if($id<1)throw new RuntimeException('Invalid destination.');$m->delete($id);setFlashMessage('Destination deleted successfully.');header('Location: destinations.php');exit;}}catch(Throwable $e){$message=$e->getMessage();$type='danger';}}
if(isset($_GET['edit']))$editing=$m->find((int)$_GET['edit']);$rows=$m->all(trim($_GET['search']??''),strtoupper(trim($_GET['status']??'')));$csrf=adminCsrfToken();adminHeader('Destinations','Manage places available to the public site and future route agent.');
?><div class="admin-card mb-4"><div class="admin-card-head"><div><h2><?= $editing?'Edit Destination':'Add Destination' ?></h2><p>Coordinates are optional now and can support future route intelligence.</p></div><?php if($editing):?><a class="btn-admin btn-light" href="destinations.php">Cancel</a><?php endif;?></div><?php if($message):?><div class="px-4 pt-3"><div class="alert alert-<?=$type?> border-0 mb-0"><?=e($message)?></div></div><?php endif;?><form method="post" class="row g-3 p-4"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($editing['id']??0)?>"><div class="col-md-5"><label class="form-label">Destination Name *</label><input class="form-control" name="name" required maxlength="150" value="<?=e($editing['name']??'')?>"></div><div class="col-md-3"><label class="form-label">State</label><input class="form-control" name="state" value="<?=e($editing['state']??'')?>"></div><div class="col-md-2"><label class="form-label">Country</label><input class="form-control" name="country" value="<?=e($editing['country']??'India')?>"></div><div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="status"><option value="ACTIVE" <?=($editing['status']??'ACTIVE')==='ACTIVE'?'selected':''?>>Active</option><option value="INACTIVE" <?=($editing['status']??'')==='INACTIVE'?'selected':''?>>Inactive</option></select></div><div class="col-md-3"><label class="form-label">Latitude</label><input class="form-control" name="latitude" type="number" step="any" value="<?=e((string)($editing['latitude']??''))?>"></div><div class="col-md-3"><label class="form-label">Longitude</label><input class="form-control" name="longitude" type="number" step="any" value="<?=e((string)($editing['longitude']??''))?>"></div><div class="col-md-6"><label class="form-label">Image Path / URL</label><input class="form-control" name="image" value="<?=e($editing['image']??'')?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4"><?=e($editing['description']??'')?></textarea></div><div class="col-12"><button class="btn-admin btn-primary"><i class="ri-save-line"></i> <?=$editing?'Update Destination':'Add Destination'?></button></div></form></div>
<div class="admin-card"><div class="admin-card-head"><div><h2>Destinations</h2><p><?=count($rows)?> destination(s)</p></div><form class="toolbar" method="get"><input class="form-control" name="search" placeholder="Search destination, state or country" value="<?=e($_GET['search']??'')?>"><select class="form-select" name="status"><option value="">All</option><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option></select><button class="btn-admin btn-primary">Search</button></form></div><div class="table-responsive"><table class="table admin-table align-middle mb-0"><thead><tr><th>Destination</th><th>Location</th><th>Coordinates</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><div class="small text-muted"><?=e($r['description']??'')?></div></td><td><?=e(trim(($r['state']??'').' · '.($r['country']??''),' ·'))?></td><td><?=($r['latitude']!==null&&$r['longitude']!==null)?e($r['latitude'].', '.$r['longitude']):'Not set'?></td><td><span class="status-pill status-<?=strtolower($r['status'])?>"><?=e($r['status'])?></span></td><td class="text-end"><a class="btn-admin btn-light btn-sm" href="destinations.php?edit=<?=(int)$r['id']?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete this destination?')"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn-admin btn-danger-soft btn-sm">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center py-5 text-muted">No destinations found.</td></tr><?php endif;?></tbody></table></div></div><?php adminFooter();
